fn main(){ let t=std::time::Instant::now(); let mut n=0; for i in 0..200000 { let s=format!("POLYGON(({} 0, 1 0, 1 1, 0 1, {} 0))", i as f64*1e-6, i as f64*1e-6); let w: wkt::Wkt<f64> = s.parse().unwrap(); let g: geo_types::Geometry<f64> = w.try_into().unwrap(); if let geo_types::Geometry::Polygon(_) = g { n+=1 } } println!("SONDA wkt {} pol/s", n as f64/t.elapsed().as_secs_f64()); let j=r#"{"type":"MultiPolygon","coordinates":[[[[0,0],[1,0],[1,1],[0,0]]]]}"#; let t=std::time::Instant::now(); for _ in 0..200000 { let g: geojson::Geometry = j.parse().unwrap(); let _: geo_types::Geometry<f64> = g.try_into().unwrap(); } println!("SONDA geojson {} /s", 200000.0/t.elapsed().as_secs_f64()); }
